/* Browser-local workbook guide. No network calls, model, or source mutations. */
(() => {
  'use strict';
  const root = window, workbook = () => root.WORKBOOK_DATA;
  const context = () => ({role:state.role, site:state.site});
  const fmt = (n,d=1) => Number.isFinite(Number(n)) ? Number(n).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d}) : 'unavailable';
  const dollars = n => Number.isFinite(Number(n)) ? Number(n).toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}) : 'unavailable';
  const total = (rows,key) => rows.reduce((n,r)=>n+(Number(r[key])||0),0);
  const scoped = (rows,site) => rows.filter(r=>site==='all'||r.site_id===site);
  const name = site => site==='all'?'All sites':workbook().sites.find(s=>s.site_id===site)?.site_name||site;
  const isFinance = () => context().role==='Supervisor';
  const permittedPage = id => typeof allowed==='function' && allowed(id);
  const chartAccess = id => typeof root.AnalyticsUI?.canChart==='function' ? root.AnalyticsUI.canChart(id) : context().role==='Supervisor'||['hse','data-quality'].includes(id)||(id==='parts'&&context().role==='Technician');
  const pageNames = {dashboard:'Dashboard',parts:'Spare Parts',hse:'HSE Actions'};
  const chartNames = {'oil-loss':'Oil loss',production:'Production',financial:'Financial impact',downtime:'Downtime','site-comparison':'Site comparison',hse:'HSE','data-quality':'Data quality',parts:'Parts readiness'};
  let panel, log, input, launcher, panelContext, lastTopic=null, lastScope=null, previousContext='', initialized=false;
  const safeText = (tag,text,cls) => {const e=document.createElement(tag);if(cls)e.className=cls;e.textContent=text;return e;};
  const editDistance = (a,b) => {if(Math.abs(a.length-b.length)>1)return 2;const row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let prior=row[0];row[0]=i;for(let j=1;j<=b.length;j++){const old=row[j];row[j]=Math.min(row[j]+1,row[j-1]+1,prior+(a[i-1]===b[j-1]?0:1));prior=old;}}return row[b.length];};
  function normalize(text){
    const terms=['dashboard','production','downtime','financial','forecast','training','technician','supervisor','security','readings','quality','compare','comparison','export','current','future','parts','safety','missing','configuration','revenue','contribution','inventory',...workbook().sites.map(s=>s.site_name.toLowerCase())];
    return text.toLowerCase().normalize('NFKC').replace(/[’']/g,'').replace(/[^a-z0-9 .%/-]/g,' ').replace(/\s+/g,' ').trim().split(' ').map(word=>word.length>=5&&!terms.includes(word)?terms.find(term=>term.length>=5&&editDistance(word,term)===1)||word:word).join(' ');
  }
  function chosenSites(q){
    if(/\b(all sites|companywide|company wide|entire company|whole company|fleet)\b/.test(q))return ['all'];
    return workbook().sites.filter(s=>new RegExp('\\b'+s.site_name.toLowerCase()+'\\b').test(q)||new RegExp('\\b'+s.site_id.toLowerCase()+'\\b').test(q)).map(s=>s.site_id);
  }
  function topicOf(q){
    if(/\b(access|permission|permissions|role|roles|security|responsible|authorization|authentication|ss[o]?|login|password)\b/.test(q))return 'access';
    if(/\b(source|sources|workbook|excel|fresh|live|updated|refresh|date|dates|provenance|duplicate|dedup|methodology|reliable)\b/.test(q))return 'source';
    if(/\b(train|training|trained|course|courses|capacity|configuration|setup|digital|staff|technicians|o6)\b/.test(q))return 'training';
    if(/\b(hse|safety|hazard|hazards|critical|severity|overdue|closure|closures|loto|h2s)\b/.test(q))return 'hse';
    if(/\b(quality|reading|readings|sensor|sensors|missing|suspect|delayed|connectivity|network|offline|uptime)\b/.test(q))return 'quality';
    if(/\b(parts|spare|spares|inventory|stock|reorder|replenishment|order|orders|receipt|receipts|automation|supplier)\b/.test(q))return 'parts';
    if(/\b(finance|financial|cost|costs|revenue|margin|contribution|dollars|money|profit|price|prices|budget)\b/.test(q))return 'financial';
    if(/\b(parts|spare|spares|inventory|stock|reorder|procurement|supply|replenishment)\b/.test(q))return 'parts';
    if(/\b(downtime|down time|outage|outages|bottleneck|bottlenecks|failure|failures|repair|dispatch|detection|stopped|reliability)\b/.test(q))return 'downtime';
    if(/\b(oil|barrels|bbl|deferred|loss|losses|lost|recovered|recovery)\b/.test(q))return 'oil';
    if(/\b(production|produced|output|volume|volumes|efficiency|efficient)\b/.test(q))return 'production';
    if(/\b(compare|comparison|versus|vs|worst|best|rank|ranking|sites)\b/.test(q))return 'comparison';
    if(/\b(dashboard|chart|charts|graph|graphs|feature|features|help|guide|navigate|navigation|page|pages|hello|hi|hey|status|overview|operations|report|reports)\b/.test(q))return 'help';
    return null;
  }
  function action(label,kind,id,site,extra={}){return {label,kind,id,site,...extra};}
  const pageAction = (id,site) => permittedPage(id)?action('Open '+pageNames[id],'page',id,site):null;
  const chartAction = (id,site,period='current') => chartAccess(id)&&(period!=='future'||['oil-loss','production','financial','site-comparison'].includes(id))?action('View '+chartNames[id]+' chart','chart',id,site,{period}):null;
  const response = (text,source='',actions=[]) => ({text,source,actions:actions.filter(Boolean)});
  function dataFor(site){const d=workbook(),ev=scoped(d.events,site).filter(e=>e.event_type==='Unplanned'),sites=scoped(d.sites,site),hse=scoped(d.hse,site),p=scoped(d.production,site);return {ev,sites,hse,p,open:hse.filter(h=>h.action_status==='Open'),hours:total(ev,'stopped_hours'),parts:total(ev,'parts_wait_hours')};}
  function monthLabel(value){return new Date(value+'T00:00:00Z').toLocaleDateString('en-US',{month:'long',year:'numeric',timeZone:'UTC'});}
  function monthly(site){const rows=dataFor(site).p;return [...new Set(rows.map(p=>p.month))].sort().map(month=>{const group=rows.filter(p=>p.month===month);return {month,produced:total(group,'produced_oil_bbl'),potential:total(group,'potential_oil_bbl'),gross:total(group,'gross_deferred_bbl'),recovered:total(group,'recovered_oil_bbl'),net:total(group,'gross_deferred_bbl')-total(group,'recovered_oil_bbl')};});}
  function answerSource(){const d=workbook(),last=d.assets.map(a=>a.latest?.observed_utc).filter(Boolean).sort().at(-1);const duplicates=d.meta.cleaning.filter(s=>s.verifiedDuplicateRowsRemoved).map(s=>s.sheet+': '+fmt(s.verifiedDuplicateRowsRemoved,0)).join('; ');return response(`The source is ${d.meta.file}. Operating records cover 2025; latest sensor records are ${last?.slice(0,10)||'not supplied'}. HSE status is the ${d.meta.hseAsOf} workbook snapshot. This site has no live feed. Forecasts, when shown, are estimates derived from historical workbook values, not live results.\n\nVerified duplicate exports were removed (${duplicates}). Missing sensor values and unknown invoices remain unavailable.`, 'ReadMe, Assets, Events, Production, Readings, HSE',[action('View source details','source')]);}
  function answerAccess(){const role=context().role;return response(`The three pages are Dashboard, Spare Parts and HSE Actions. ${role==='Supervisor'?'Supervisors can configure inventory and site rules, review replenishment requests, approve or cancel demo orders, and record stock movements.':role==='Technician'?'Technicians can inspect stock, record issues/counts and receive approved demo orders. They cannot configure automation or approve requests.':'HSE Supervisors can inspect Spare Parts in read-only mode and review safety actions.'}\n\nFinancial chart permissions remain role-specific. The page role selector and HSE Demo role are demonstrations, not production authentication. The guide can explain and navigate; it cannot approve purchases or alter records.`, 'Application view and workflow design',[pageAction('parts',context().site),pageAction('hse',context().site)]);}

  function answerHse(site,q){const d=dataFor(site),critical=d.open.filter(h=>h.potential_severity===5),hours=total(d.open,'action_person_hours'),closed=d.hse.filter(h=>h.action_status==='Closed');const due=d.open.filter(h=>h.due_date&&h.due_date<workbook().meta.hseAsOf);let text=`${name(site)} ${site==='all'?'have':'has'} ${d.open.length} open HSE actions, including ${critical.length} severity-5 actions, and ${closed.length} closed actions. Open actions require ${fmt(hours,0)} person-hours in the workbook. ${due.length} open actions were overdue at the source snapshot (${workbook().meta.hseAsOf}).`;if(/\b(critical|worst|hazard|hazards|list|which|h2s|loto)\b/.test(q)&&critical.length)text+='\n\nCritical open records: '+critical.map(h=>`${h.hse_id} · ${name(h.site_id)} · ${h.hazard}`).join('; ')+'.';return response(text,'HSE · source status snapshot',[pageAction('hse',site),chartAction('hse',site)]);}
  function answerParts(site,q){const d=dataFor(site),waits=d.ev.filter(e=>e.parts_wait_hours>0),fill=d.sites.map(s=>`${s.site_name} ${fmt(s.spare_fill_pct,0)}%`).join(', ');const items=root.PartsStore?.getItems(site)||[],orders=root.PartsStore?.getOrders(site)||[],pending=orders.filter(o=>o.status==='Pending approval'),active=orders.filter(o=>['Pending approval','Approved','Partially received'].includes(o.status));let text=`${name(site)} · ${items.length} demo inventory records, ${active.length} open demo orders, ${pending.length} awaiting approval. The workbook does not supply a part catalog, inventory balances, suppliers or purchase orders. New entries are simulated and saved in this browser.\n\n2025 source history: ${fmt(d.parts)} parts-wait equipment-hours across ${waits.length} unplanned events. Local spare fill: ${fill}.`;
    if(/\b(auto|automatic|automated|automation|reorder|replenishment|rule|rules)\b/.test(q))text+='\n\nEnable auto-replenishment for each site and configure a part’s stock count, reorder point and target. When inventory position (on hand + outstanding order quantity) reaches the reorder point, the app creates one request for target minus inventory position. An existing open request prevents duplicates. Requests require HSE gate clearance and Supervisor approval; no purchase is sent to a supplier.';
    if(/\b(receive|receipt|receipts|receive[d]?)\b/.test(q))text+='\n\nOnce the site safety gate is CLEAR, open Orders, choose an approved order, enter the received quantity and a reference. Partial receipts update stock and remaining quantity. Receiving more than the remaining amount is blocked.';
    if(/\b(start|help|how|demo|try|add|configure)\b/.test(q))text+='\n\nStart with Add part, choose its site and asset, and enter counts and thresholds. Or choose Try demo to load an explicitly simulated kit for one site. Supervisors configure and approve; technicians record movements and approved receipts; HSE Supervisors have read-only parts access.';
    return response(text,'Workbook history + separately stored demo inventory',[action('Open inventory','parts-tab','inventory',site),action('Open orders','parts-tab','orders',site),action('Open automation','parts-tab','automation',site)]);}

  function answerDowntime(site,q){if(!isFinance())return response('Detailed downtime analysis is restricted to the Supervisor dashboard. Your current pages include Spare Parts and HSE Actions.','Application permission design',[pageAction('parts',site),pageAction('hse',site)]);const d=dataFor(site),causes=[...new Set(d.ev.map(e=>e.cause))].map(c=>[c,total(d.ev.filter(e=>e.cause===c),'stopped_hours')]).sort((a,b)=>b[1]-a[1]);const stages=[['Detection','detect_hours'],['Dispatch','dispatch_hours'],['Parts wait','parts_wait_hours'],['Repair','repair_hours'],['Restart','restart_hours']].map(([label,key])=>[label,total(d.ev,key)]).sort((a,b)=>b[1]-a[1]);let text=`${name(site)} recorded ${fmt(d.hours)} unplanned equipment-hours across ${d.ev.length} events in 2025 (${fmt(d.ev.length?d.hours/d.ev.length:0)} h per event).`;if(causes[0])text+=` Largest cause: ${causes[0][0]}, ${fmt(causes[0][1])} h (${fmt(causes[0][1]/d.hours*100)}%).`;if(stages[0])text+=` Largest delay stage: ${stages[0][0]}, ${fmt(stages[0][1])} h.`;if(/\b(stage|stages|breakdown|bottleneck|bottlenecks)\b/.test(q))text+='\n\n'+stages.map(([n,h])=>n+': '+fmt(h)+' h').join('; ')+'.';text+='\n\nCause categories and delay stages describe the same events; do not add them together.';return response(text,'Events · Unplanned records only',[chartAction('downtime',site),pageAction('parts',site)]);}
  function answerTraining(site,q){const d=dataFor(site),technicians=total(d.sites,'technicians'),hours=total(d.sites,'training_required_hours'),capacity=total(d.sites,'available_project_hours'),o=workbook().options.find(o=>o.option_id==='O6');let text=`${name(site)} ${site==='all'?'have':'has'} ${fmt(technicians,0)} technicians, ${fmt(hours,0)} required training hours, and ${fmt(capacity,0)} available project hours. Training hours are technicians × site training hours per person. The workbook does not provide employee identities, attendance, completion, or configuration-task status.`;if(o)text+=`\n\nO6 (${o.option_name}): ${o.benefit_rule}. Lead time: ${fmt(o.lead_months,0)} month${o.lead_months===1?'':'s'}.`;if(isFinance()&&/\b(cost|budget|setup|configuration|digital|price)\b/.test(q))text+=` Source configuration inputs across selected sites: cleanup ${dollars(total(d.sites,'cleanup_setup_usd'))}; edge setup ${dollars(total(d.sites,'edge_setup_usd'))}; annual edge ${dollars(total(d.sites,'edge_annual_usd'))}. These are workbook options, not approved purchases.`;return response(text,'Assets, Solutions · O6',[pageAction('setup',site)]);}
  function answerQuality(site){const d=dataFor(site),missing=d.sites.reduce((n,s)=>n+(s.readings.quality_counts.Missing||0),0),suspect=d.sites.reduce((n,s)=>n+(s.readings.quality_counts.Suspect||0),0),late=d.sites.reduce((n,s)=>n+(s.readings.delayed_over_1h_count||0),0);return response(`${name(site)} ${site==='all'?'have':'has'} ${fmt(missing,0)} Missing readings, ${fmt(suspect,0)} Suspect readings, and ${fmt(late,0)} readings received more than one hour late in 2025. Network uptime: ${d.sites.map(s=>s.site_name+' '+fmt(s.network_uptime_pct)+'%').join(', ')}.\n\nNetwork uptime measures connectivity, not production availability. Suspect readings are not confirmed equipment failures. Missing values are not treated as zero.`, 'Readings, Assets · 2025',[chartAction('data-quality',site),pageAction('setup',site)]);}
  function answerProduction(site,q,oil=false){if(!isFinance())return response('Production and oil-loss analysis are available in the Supervisor view. I can help you inspect safety, training, and reading quality in your current view.','Application permission design',[pageAction('hse',site),pageAction('setup',site)]);const rows=monthly(site),p=dataFor(site).p,gross=total(p,'gross_deferred_bbl'),recovered=total(p,'recovered_oil_bbl'),produced=total(p,'produced_oil_bbl'),potential=total(p,'potential_oil_bbl');let text=oil?`${name(site)} recorded ${fmt(gross,0)} bbl gross deferred oil and ${fmt(recovered,0)} bbl recovered oil in 2025. Net unrecovered deferral is ${fmt(gross-recovered,0)} bbl (gross deferred − recovered).`:`${name(site)} produced ${fmt(produced,0)} bbl against ${fmt(potential,0)} bbl potential in 2025. Recorded production / potential is ${fmt(potential?produced/potential*100:0)}%.`;if(rows.length){const metric=oil?'net':'produced',first=rows[0],last=rows.at(-1),diff=last[metric]-first[metric];text+=`\n\n${monthLabel(first.month)} to ${monthLabel(last.month)}: ${fmt(first[metric],0)} → ${fmt(last[metric],0)} bbl (${diff>=0?'+':''}${fmt(diff,0)} bbl). This is an endpoint comparison, not proof of a sustained trend.`;}if(oil)text+=' Gross oil deferral and downtime are related measures, not separate benefits to add.';return response(text,'Production · monthly records; calculated totals',[chartAction(oil?'oil-loss':'production',site)]);}
  function answerFinance(site,q=''){
    if(!isFinance())return response('Financial values and financial exports are restricted to the Supervisor view. I cannot reveal or export them through the guide.','Application permission design',[pageAction('dashboard',site)]);
    const rows=dataFor(site).p;
    if(/\b(price|prices|variable cost|oil price)\b/.test(q)){const prices=rows.map(r=>r.price_usd_bbl),variable=rows.map(r=>r.variable_cost_usd_bbl);return response(`${name(site)} · 2025 source oil prices range from ${dollars(Math.min(...prices))} to ${dollars(Math.max(...prices))} per bbl; variable costs range from ${dollars(Math.min(...variable))} to ${dollars(Math.max(...variable))} per bbl. These are workbook asset-month inputs, not current market prices.`, 'Production · price_usd_bbl, variable_cost_usd_bbl',[chartAction('financial',site)]);}
    const value=root.LMEAnalytics?.monetary?.(site);
    if(!value)return response('Open the Financial impact chart to inspect source-based contribution loss and calculation definitions. This measure is not booked loss, realized savings, or complete maintenance expense.','Production, Events',[chartAction('financial',site)]);
    return response(`${name(site)} recorded ${dollars(value.net_contribution_loss_usd)} in modeled net deferred contribution for 2025.\n\nCalculation: sum of each asset-month’s (gross deferred − recovered oil) × (oil price − variable cost). This matches the Financial impact chart’s Production-sheet basis. It is not gross revenue, cash savings, or complete maintenance expense. Event-level attribution differs slightly due to source rounding; do not add it a second time.`, 'Production · calculated historical net deferred contribution',[chartAction('financial',site)]);
  }
  function answerComparison(site,q,mentioned){
    const sites=mentioned.length>1?workbook().sites.filter(s=>mentioned.includes(s.site_id)):workbook().sites;
    const metric=/\b(hse|safety|critical|hazard)\b/.test(q)?'hse':/\b(network|uptime|connectivity|quality)\b/.test(q)?'quality':/\b(parts|fill|spares)\b/.test(q)?'parts':/\b(financial|cost|revenue|contribution|money|profit)\b/.test(q)?'financial':/\b(production|produced|output)\b/.test(q)?'production':/\b(oil|loss|lost|deferred)\b/.test(q)?'oil':isFinance()?'downtime':'hse';
    if(['financial','production','oil','downtime'].includes(metric)&&!isFinance())return response('That comparison is restricted to the Supervisor view. I can compare source safety actions or connectivity in your current view.','Application permission design',[chartAction('hse',site),chartAction('data-quality',site)]);
    if(metric==='parts'&&!permittedPage('parts'))return answerParts(site,q);
    const results=sites.map(s=>{const d=dataFor(s.site_id),p=d.p;let value;if(metric==='hse')value=d.open.filter(h=>h.potential_severity===5).length;else if(metric==='quality')value=s.network_uptime_pct;else if(metric==='parts')value=d.parts;else if(metric==='financial')value=root.LMEAnalytics?.monetary?.(s.site_id).net_contribution_loss_usd;else if(metric==='production')value=total(p,'produced_oil_bbl');else if(metric==='oil')value=total(p,'gross_deferred_bbl')-total(p,'recovered_oil_bbl');else value=d.hours;return {site:s,value};}).sort((a,b)=>metric==='quality'?a.value-b.value:b.value-a.value);
    const labels={hse:'Critical open HSE actions',quality:'Network uptime',parts:'Parts-wait hours',downtime:'Unplanned equipment-hours',financial:'Modeled contribution loss',production:'Produced oil',oil:'Net unrecovered oil deferral'},unit=metric==='quality'?'%':metric==='hse'?'':['oil','production'].includes(metric)?' bbl':' h';
    return response(`${labels[metric]} by site:\n${results.map((r,i)=>`${i+1}. ${r.site.site_name}: ${metric==='financial'?dollars(r.value):fmt(r.value,metric==='hse'?0:1)+unit}`).join('\n')}\n\n${metric==='quality'?'Lowest connectivity appears first.':metric==='hse'?'Equal counts are ties, not a risk-score ranking.':'Largest recorded total appears first; this does not adjust for asset exposure or site size.'}`,metric==='hse'?'HSE · '+workbook().meta.hseAsOf:metric==='quality'?'Assets':['oil','production'].includes(metric)?'Production · 2025':metric==='financial'?'Events, Production · 2025':'Events · 2025',[metric==='parts'?action('Open spare-parts comparison','parts-analysis','dashboard','all'):chartAction(metric==='hse'?'hse':metric==='quality'?'data-quality':metric==='parts'?'parts':metric==='downtime'?'downtime':metric==='financial'?'financial':metric==='production'?'production':'site-comparison','all')]);
  }
  function answerPriority(){
    const d=dataFor('S04'),all=dataFor('all'),other=workbook().sites.filter(s=>s.site_id!=='S04'),affected=d.ev.filter(e=>e.parts_wait_hours>0),otherEvents=all.ev.filter(e=>e.site_id!=='S04'&&e.parts_wait_hours>0);
    const fill=other.reduce((n,s)=>n+s.spare_fill_pct,0)/other.length;
    return response(`Arroyo is the first spare-parts priority in the 2025 workbook: ${fmt(d.parts)} parts-wait hours, or ${fmt(d.parts/all.parts*100)}% of the company total, and ${affected.length} affected events. Both totals are highest among the six sites. Local spare fill is ${fmt(d.sites[0].spare_fill_pct,0)}%, the lowest case planning input (not a live stock count), compared with ${fmt(fill)}% as the simple average of the other five sites.\n\nAverage wait per affected event is ${fmt(d.parts/affected.length,2)} h at Arroyo and ${fmt(total(otherEvents,'parts_wait_hours')/otherEvents.length,2)} h across the other sites combined. The evidence shows more affected events, not longer individual waits. It does not establish which SKU was missing or prove that stock availability caused every delay.\n\nH019 and H020 are Arroyo’s open severity-5 source actions. Review those separately in HSE Actions; historical source status and simulated verification remain separate.`, 'Assets · local spare fill; Events · 2025 unplanned records; HSE · Oct 1, 2026', [pageAction('dashboard','S04'),action('Open Arroyo inventory','parts-tab','inventory','S04'),pageAction('hse','S04')]);
  }
  function answerHelp(){const role=context().role;return response(`Use Spare Parts to track inventory by site, configure replenishment rules, review requests and record receipts. Spare Parts opens first with Arroyo’s historical overview and the inventory tracker. Dashboard explains why Arroyo is the first priority, compares sites and shows potential HSE severity. HSE Actions contains the safety workflow.\n\nTry: “Show Arroyo inventory”, “How does auto-replenishment work?”, “Open orders”, “Why is Arroyo the priority?”, or “Show critical HSE actions”.\n\nI can explain data and open permitted views for your ${role} role. I run locally without a language model, live inventory feed or supplier connection.`, 'Workbook guide capabilities',[pageAction('parts',context().site),pageAction('dashboard',context().site),pageAction('hse',context().site)]);}

  function answerFuture(site,topic,q){
    if(['hse','quality','training','parts','access','downtime'].includes(topic))return response(`There is no future ${topic==='hse'?'safety closure':topic==='quality'?'sensor quality':topic==='training'?'training completion':topic==='parts'?'inventory':topic==='downtime'?'downtime':'user access'} series in this interface. I will not invent future records. ${isFinance()?'Supported projections cover oil loss, production, financial impact, and site comparisons.':''}`, 'Historical workbook records',[isFinance()?chartAction('production',site,'future'):pageAction(topic==='training'?'setup':'hse',site)]);
    if(!isFinance())return response('Operational forecasts are restricted to the Supervisor view. Your current view includes historical safety and training records.','Application permission design',[pageAction('hse',site)]);
    const id=topic==='oil'?'oil-loss':topic==='financial'?'financial':topic==='comparison'?'site-comparison':'production',p=root.LMEAnalytics?.projection?.(site);
    if(!p)return response('The forecast chart uses a fixed January–March 2026 historical baseline fitted to 2025 source records. It is not a current forecast or a live feed.','Production, Events · historical inputs',[chartAction(id,site,'future')]);
    const t=p.totals, metric=topic==='financial'?'contribution_loss_usd':topic==='oil'?'net_lost_bbl':'produced_bbl',validation=p.backtest.metrics.find(m=>m.metric===metric);
    let text=`${name(site)} · ${p.period} historical-baseline projection, using data through ${p.as_of}:\n${topic==='financial'?dollars(t.contribution_loss_usd)+' modeled contribution loss.':topic==='oil'?fmt(t.net_lost_bbl,0)+' bbl net lost ('+fmt(t.gross_deferred_bbl,0)+' bbl gross deferred minus '+fmt(t.recovered_bbl,0)+' bbl recovered).':fmt(t.produced_bbl,0)+' bbl produced against '+fmt(t.potential_bbl,0)+' bbl potential.'}\n\nMethod: each asset’s 2025 average volume per calendar-hour × projected month hours; source capacity and calendar-hour-weighted margins stay fixed. No growth, intervention benefit, or seasonality is assumed. This is not a current forecast as of today.`;
    if(/\b(how|method|calculated|calculate|accuracy|accurate|validation|backtest|reliable|error|range|confidence|why)\b/.test(q)&&validation)text+=`\n\nA January–September 2025 fit was checked against October–December 2025: ${fmt(validation.wape_pct)}% WAPE for ${topic==='financial'?'contribution loss':topic==='oil'?'net lost oil':'produced oil'}. WAPE = total absolute error ÷ total actual. This is only three holdout months, not a guaranteed accuracy rate. The model’s historical variability is descriptive, not a confidence interval.`;
    return response(text,'Production, Assets, Events · source-derived baseline projection',[chartAction(id,site,'future')]);
  }
  function routeFor(topic){return {hse:'hse',parts:'parts',help:'dashboard',comparison:'dashboard',downtime:'dashboard',quality:'dashboard',access:'parts'}[topic];}
  function chartFor(topic){return {oil:'oil-loss',production:'production',financial:'financial',downtime:'downtime',hse:'hse',quality:'data-quality',comparison:'site-comparison',parts:'parts'}[topic];}
  function exportFor(topic){return {hse:'hse',parts:'parts',help:'operations',comparison:'operations'}[topic];}
  function recordAnswer(q){
    const match=(rows,key)=>rows.find(r=>new RegExp('\\b'+r[key].toLowerCase()+'\\b').test(q));
    let r=match(workbook().hse,'hse_id');
    if(r&&permittedPage('hse'))return response(`${r.hse_id} · ${name(r.site_id)} · ${r.hazard}. Source status: ${r.action_status}; severity ${r.potential_severity}/5; due ${r.due_date}; owner ${r.action_owner}. Control gap: ${r.control_gap}.`, 'HSE · row '+r.source.row,[action('View '+r.hse_id,'record',r.hse_id,r.site_id,{recordKind:'hse'})]);
    r=match(workbook().assets,'asset_id');
    if(r)return response(`${r.asset_id} · ${name(r.site_id)} · ${r.asset_type}. Latest source observation: ${r.latest.observed_utc}; recorded state ${r.latest.operating_state}; quality ${r.latest.quality}. This historical observation is not current equipment status.`, 'Assets; Readings · source observation',[action('View '+r.asset_id,'record',r.asset_id,r.site_id,{recordKind:'asset'})]);
    r=match(workbook().events,'event_id');
    if(r){if(context().role!=='Supervisor'&&!(permittedPage('parts')&&r.parts_wait_hours>0))return response('This event is outside the record access available in your current role.','Application permission design');return response(`${r.event_id} · ${name(r.site_id)} · ${r.asset_id}. ${r.event_type} event: ${r.cause}; ${fmt(r.stopped_hours)} stopped hours and ${fmt(r.parts_wait_hours)} parts-wait hours. Started ${r.start_utc}.`, 'Events · row '+r.source.row,[action('View '+r.event_id,'record',r.event_id,r.site_id,{recordKind:'event'})]);}
    return null;
  }
  function ask(text){
    const raw=String(text||'').trim().slice(0,600),q=normalize(raw),mentioned=chosenSites(q);if(!q)return answerHelp();
    if(/\b(change|switch|grant|become|set|make|unlock)\b.*\b(role|supervisor|technician|permission|admin|access)\b/.test(q)||/\b(ignore|bypass|override)\b.*\b(permission|role|restriction|guard|rule)\b/.test(q))return response('I cannot change roles, grant access, or bypass permissions. I only navigate and report within your current view.','Application permission design',[pageAction('parts',context().site)]);
    if(/\b(approve|authorize|delete|verify closure|close action|mark complete|update source|edit source|write source|start equipment|stop equipment)\b/.test(q)||/^(please )?(purchase|buy|place|submit|cancel|receive|issue|adjust)\b/.test(q))return response('Use the relevant demo workflow to record stock movements, review requests or verify safety work. I can explain and navigate, but cannot approve purchases, modify workbook records or operate equipment.','Guide actions are read-only',[pageAction(/\b(hse|safety|closure|action)\b/.test(q)?'hse':'parts',context().site)]);
    if(/\b(export|download)\b/.test(q)&&/\b(inventory|orders?|requests?|receipts?)\b/.test(q))return response('Demo inventory and request exports are not available. Use Spare Parts to inspect those records. The workbook report contains historical site metrics only.','Application export scope',[pageAction('parts',context().site)]);
    if(/\b(hold|locked|unlock|safety gate)\b/.test(q)){
      const ids=mentioned.length?mentioned:[context().site],sites=ids.includes('all')?workbook().sites:workbook().sites.filter(s=>ids.includes(s.site_id));
      const lines=sites.map(s=>{const g=root.HSEActionDetails?.gate(s.site_id);return s.site_name+': '+(!g?'HOLD - safety status unavailable.':g.held?'HOLD - '+g.unresolved.length+' critical action(s) still need HSE Supervisor verification.':'CLEAR - standard request approval applies.');});
      return response(lines.join('\n')+'\n\nRequests may queue while on HOLD, but approval and receipt are locked. Open each critical action, submit a completion note, then select the HSE Supervisor demo role and record a verification note. One verified closure does not clear a site with another unresolved critical action. Reset restores its hold. This is a browser-local demo gate, not an equipment control.','Source HSE critical actions + separate demo verification',[pageAction('parts',mentioned.length===1?mentioned[0]:context().site)]);
    }
    const kit=root.SparePartsModel?.suggestKit(raw);
    if(kit?.matched||/\b(smart note|note sorting|kit|kits)\b/.test(q))return response(kit?.matched?kit.kit+'. This is a note-to-kit lookup suggestion. Confirm the kit and follow site procedures. It does not create inventory or a request.':'In Spare Parts, pick or type a note under Smart note sorting: noise and vibration suggests Bearing kit; visible leak suggests Seal kit; protective trip at an electrical panel suggests Electrical kit; changed feed conditions suggests No part, restart check; an unconfirmed cause suggests Inspect first. Unknown or conflicting notes also require inspection.','Proposed note-to-kit lookup rules',[pageAction('parts',context().site)]);
    if(/\barroyo\b/.test(q)&&/\b(why|priority|important|first|focus|recommend)\b/.test(q))return answerPriority();
    const record=recordAnswer(q);if(record){if(/^(please\s+)?(show|open|review)\b/.test(q)&&record.actions[0])execute(record.actions[0]);return record;}
    let topic=topicOf(q);const future=/\b(future|forecast|prediction|predict|projected|projection|next year|2026|2027)\b/.test(q)&&!(/\b(hse|snapshot|source|date)\b/.test(q)&&! /\b(future|forecast|predict)\b/.test(q));
    if(future&&/\b202[7-9]\b|\b20[3-9][0-9]\b/.test(q))return response('Only the fixed January–March 2026 historical-baseline projection is available, using data through December 31, 2025. I cannot supply a different forecast year or invent current inputs.','Projection methodology',[chartAction('production',context().site,'future')]);
    if(!topic&&future)topic=['oil','production','financial','comparison'].includes(lastTopic)?lastTopic:'production';
    if(!topic&&(future||mentioned.length||/\b(what about|and that|more|explain it|why|how calculated)\b/.test(q)))topic=lastTopic;
    if(!topic&&/\b(show|open|switch|select|filter)\b/.test(q)&&mentioned.length)topic='help';
    const site=mentioned.length===1?mentioned[0]:mentioned.length>1?'all':lastScope&&/\b(what about|and that|more|explain it|future|forecast)\b/.test(q)?lastScope:context().site;
    if(!topic)return response('I could not match that request to this workbook or the site controls. I can help with Spare Parts inventory, order rules and receipts, HSE, historical charts, source dates, and permitted exports. Try asking one question about one of those areas.','Browser-local guide; no general-purpose model',[pageAction('dashboard',context().site)]);
    lastTopic=topic;lastScope=site;
    let result;
    const compare=/\b(compare|comparison|versus|vs|rank|ranking|worst|best|which site|highest|lowest)\b/.test(q)||mentioned.length>1;
    if(topic==='source'&&!future)result=answerSource();else if(topic==='access')result=answerAccess();else if(future)result=answerFuture(site,topic,q);else if(compare&&topic!=='training')result=answerComparison(site,q,mentioned);else result=({hse:()=>answerHse(site,q),parts:()=>answerParts(site,q),downtime:()=>answerDowntime(site,q),training:()=>answerTraining(site,q),quality:()=>answerQuality(site),production:()=>answerProduction(site,q),oil:()=>answerProduction(site,q,true),financial:()=>answerFinance(site,q),comparison:()=>answerComparison(site,q,mentioned),help:()=>answerHelp()})[topic]();
    const explicit=/^(please\s+)?(show|open|take me|go to|navigate|display|switch|select|filter|export|download)\b/.test(q)||/\b(can|could|would) you (show|open|take me|export|download|switch|filter)\b/.test(q);
    if(explicit){
      let command=null;
      if(/\b(export|download)\b/.test(q)){const type=exportFor(topic);if(type&&canExport(type))command=action('Export report','export',type,site);else result=response('That export is not available for your role or this data view. I cannot create a broader export or bypass the restriction.','Application permission design',result.actions);}
      else if(/\b(switch|select|filter)\b/.test(q)&&mentioned.length===1)command=action('Select '+name(site),'site',site,site);
      else if(topic==='source')command=action('View source details','source');
      else if(topic==='parts'&&!/\b(chart|graph|trend|compare|comparison)\b/.test(q))command=action('Open Spare Parts','parts-tab',/\b(order|orders|receipt|receipts)\b/.test(q)?'orders':/\b(automation|reorder|rule|rules|auto)\b/.test(q)?'automation':'inventory',site);
      else if(topic==='help'&&/\b(chart|charts|dashboard|overview)\b/.test(q))command=action('Open chart overview','overview','dashboard',site);
      else if(topic==='hse'&&/\b(closed|open|severity [1-5])\b/.test(q)&&permittedPage('hse'))command=action('Filter HSE actions','hse-filter','hse',site,{status:/\bclosed\b/.test(q)?'Closed':/\bopen\b/.test(q)?'Open':'all',severity:q.match(/\bseverity ([1-5])\b/)?.[1]||'all'});
      else {const id=chartFor(topic),page=routeFor(topic);if(id&&(future||/\b(chart|graph|trend|oil|production|financial|forecast)\b/.test(q))&&chartAccess(id))command=chartAction(id,site,future?'future':'current');else if(page&&permittedPage(page))command=pageAction(page,site);}
      if(command){const success=execute(command);if(success)result={...result,text:command.kind==='export'?'Exported the permitted report for '+name(site)+'.\n\n'+result.text:result.text,executed:command};}
    }
    return result;
  }
  function execute(a){
    if(!a)return false;
    if(a.kind==='page'&&!permittedPage(a.id))return false;
    if(a.kind==='parts-analysis'&&!permittedPage('dashboard'))return false;
    if(a.kind==='parts-tab'&&(!permittedPage('parts')||!['inventory','orders','automation'].includes(a.id)))return false;
    if(a.kind==='chart'&&!chartAccess(a.id))return false;
    if(a.kind==='chart'&&a.period==='future'&&!['oil-loss','production','financial','site-comparison'].includes(a.id))return false;
    if(a.kind==='hse-filter'&&!permittedPage('hse'))return false;
    if(a.kind==='export'&&!canExport(a.id))return false;
    if(a.site&&a.site!=='all'&&!workbook().sites.some(s=>s.site_id===a.site))return false;
    if(a.site&&a.site!==context().site)changeSite(a.site);
    if(a.kind==='page'){location.hash=a.id;return true;}
    if(a.kind==='parts-tab'){location.hash='parts';root.SpareParts.showTab(a.id);return true;}
    if(a.kind==='parts-analysis'){root.AnalyticsUI.showOverview();return true;}
    if(a.kind==='overview'){if(typeof root.AnalyticsUI?.showOverview==='function')root.AnalyticsUI.showOverview();else location.hash='dashboard';return true;}
    if(a.kind==='hse-filter'){state.hseStatus=['Open','Closed','all'].includes(a.status)?a.status:'all';state.hseSeverity=['1','2','3','4','5'].includes(a.severity)?a.severity:'all';state.page=0;if(location.hash==='#hse')render();else location.hash='hse';return true;}
    if(a.kind==='site'){changeSite(a.id);return true;}
    if(a.kind==='source'){details();return true;}
    if(a.kind==='record')return openRecord(a.recordKind,a.id);
    if(a.kind==='chart'){if(typeof root.AnalyticsUI?.openChart!=='function')return false;root.AnalyticsUI.openChart(a.id,a.period||'current');return true;}
    if(a.kind==='export')return exportReport(a.id);
    return false;
  }
  function append(text,type='bot',source='',actions=[]){
    const item=safeText('div','', 'assist-message '+type);item.append(safeText('div',text,'assist-body'));if(source)item.append(safeText('div','Source: '+source,'assist-source'));
    if(actions.length){const group=safeText('div','','assist-actions');actions.forEach(a=>{const button=safeText('button',a.label);button.type='button';button.addEventListener('click',()=>{if(!execute(a))append('This action is unavailable in the current view.');});group.append(button);});item.append(group);}log.append(item);while(log.children.length>24)log.firstElementChild.remove();log.scrollTop=log.scrollHeight;
  }
  function clear(){if(!initialized)return;log.replaceChildren();lastTopic=null;lastScope=null;const c=context();previousContext=c.role+'|'+c.site;panelContext.textContent=c.role+' · '+name(c.site);append('Ask why Arroyo comes first, or explore spare parts, orders and HSE actions. I can explain the workflow and open permitted views. I run locally and do not send supplier purchases.');}
  function submit(text){if(!String(text).trim())return;append(String(text).slice(0,600),'user');let result;try{result=ask(text);}catch(error){result=response('I could not complete that request. Please ask about a specific site metric or page. No source records were changed.');}append(result.text,'bot',result.source,result.actions);input.value='';input.focus();return result;}
  function open(){init();panel.hidden=false;launcher.setAttribute('aria-expanded','true');input.focus();}
  function close(){panel.hidden=true;launcher.setAttribute('aria-expanded','false');launcher.focus();}
  function init(){if(initialized)return;initialized=true;
    launcher=safeText('button','Workbook guide','assist-launch');launcher.type='button';launcher.setAttribute('aria-controls','site-assistant');launcher.setAttribute('aria-expanded','false');launcher.addEventListener('click',()=>panel.hidden?open():close());
    panel=safeText('section','','assist-panel');panel.id='site-assistant';panel.hidden=true;panel.setAttribute('aria-label','Workbook guide');
    const header=safeText('div','','assist-head'),title=safeText('div');title.append(safeText('h2','Workbook guide'),safeText('small','Runs locally · workbook answers'));const x=safeText('button','×');x.type='button';x.setAttribute('aria-label','Close workbook guide');x.addEventListener('click',close);header.append(title,x);
    panelContext=safeText('div','','assist-context');log=safeText('div','','assist-messages');log.setAttribute('role','log');log.setAttribute('aria-live','polite');log.setAttribute('aria-relevant','additions');
    const suggestions=safeText('div','','assist-suggestions');['Critical HSE actions','Explain data quality','Training requirements'].forEach(text=>{const b=safeText('button',text);b.type='button';b.addEventListener('click',()=>submit(text));suggestions.append(b);});
    const form=safeText('form','','assist-inputrow');input=document.createElement('input');input.type='text';input.maxLength=600;input.placeholder='Ask about this site…';input.setAttribute('aria-label','Ask the workbook guide');input.autocomplete='off';const send=safeText('button','Send');send.type='submit';form.append(input,send);form.addEventListener('submit',e=>{e.preventDefault();submit(input.value);});
    panel.append(header,panelContext,log,suggestions,form,safeText('div','Historical workbook · role-aware navigation · no source edits','assist-note'));document.body.append(launcher,panel);
    panel.addEventListener('keydown',e=>{if(e.key==='Escape')close();});root.addEventListener('viewchange',()=>{const c=context();if(previousContext!==c.role+'|'+c.site)clear();});document.getElementById('role')?.addEventListener('change',clear);document.getElementById('site-scope')?.addEventListener('change',clear);clear();
  }
  root.SiteAssistant=Object.freeze({init,open,close,clear,ask,execute,submit});
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
